import React, { useEffect, useRef } from 'react';
import { motion } from 'motion/react';
import { CalendarPlus, CheckCircle2, Clock3, Copy, Pencil, Trash2 } from 'lucide-react';
import type { CalendarOccurrence } from './calendarModel';

interface CalendarContextMenuProps {
  x: number;
  y: number;
  occurrence: CalendarOccurrence | null;
  onClose: () => void;
  onCreate: (kind: 'event' | 'focus') => void;
  onOpenDay: () => void;
  onEdit: () => void;
  onDuplicate: () => void;
  onToggleDone: () => void;
  onDelete: () => void;
}

export const CalendarContextMenu: React.FC<CalendarContextMenuProps> = ({
  x,
  y,
  occurrence,
  onClose,
  onCreate,
  onOpenDay,
  onEdit,
  onDuplicate,
  onToggleDone,
  onDelete,
}) => {
  const menuRef = useRef<HTMLDivElement>(null);
  const viewportWidth = typeof window === 'undefined' ? 1280 : window.innerWidth;
  const viewportHeight = typeof window === 'undefined' ? 800 : window.innerHeight;
  const left = Math.max(10, Math.min(x, viewportWidth - 238));
  const top = Math.max(10, Math.min(y, viewportHeight - (occurrence ? 286 : 190)));

  useEffect(() => {
    const close = (event: Event) => {
      if (!menuRef.current?.contains(event.target as Node)) onClose();
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose();
    };
    document.addEventListener('pointerdown', close);
    window.addEventListener('resize', onClose);
    window.addEventListener('scroll', onClose, true);
    window.addEventListener('keydown', onKeyDown);
    requestAnimationFrame(() => menuRef.current?.querySelector<HTMLButtonElement>('button')?.focus());
    return () => {
      document.removeEventListener('pointerdown', close);
      window.removeEventListener('resize', onClose);
      window.removeEventListener('scroll', onClose, true);
      window.removeEventListener('keydown', onKeyDown);
    };
  }, [onClose]);

  const itemClass = 'flex min-h-10 w-full items-center gap-3 rounded-xl px-3 text-left text-sm font-medium text-white/72 outline-none transition hover:bg-white/[0.075] hover:text-white focus-visible:bg-white/[0.09] focus-visible:text-white';

  return (
    <motion.div
      ref={menuRef}
      role="menu"
      aria-label={occurrence ? 'Event actions' : 'Day actions'}
      initial={{ opacity: 0, scale: 0.96, y: -5 }}
      animate={{ opacity: 1, scale: 1, y: 0 }}
      transition={{ type: 'spring', stiffness: 430, damping: 32 }}
      className="wersee-liquid-glass wersee-liquid-glass--thick fixed z-[360] w-56 rounded-[1.25rem] border border-white/[0.1] p-2 shadow-[0_24px_80px_rgba(0,0,0,.62)]"
      style={{ left, top }}
      onContextMenu={(event) => event.preventDefault()}
    >
      {occurrence ? (
        <>
          <button type="button" role="menuitem" className={itemClass} onClick={onEdit}><Pencil className="h-4 w-4 text-violet-300" /> Edit event</button>
          <button type="button" role="menuitem" className={itemClass} onClick={onToggleDone}><CheckCircle2 className="h-4 w-4 text-emerald-300" /> {occurrence.status === 'done' ? 'Mark scheduled' : 'Mark complete'}</button>
          <button type="button" role="menuitem" className={itemClass} onClick={onDuplicate}><Copy className="h-4 w-4 text-sky-300" /> Duplicate</button>
          <div className="my-1 h-px bg-white/[0.07]" />
          <button type="button" role="menuitem" className={`${itemClass} text-red-300 hover:bg-red-500/10 hover:text-red-200`} onClick={onDelete}><Trash2 className="h-4 w-4" /> Delete</button>
        </>
      ) : (
        <>
          <button type="button" role="menuitem" className={itemClass} onClick={() => onCreate('event')}><CalendarPlus className="h-4 w-4 text-violet-300" /> New event</button>
          <button type="button" role="menuitem" className={itemClass} onClick={() => onCreate('focus')}><Clock3 className="h-4 w-4 text-amber-300" /> Add focus block</button>
          <div className="my-1 h-px bg-white/[0.07]" />
          <button type="button" role="menuitem" className={itemClass} onClick={onOpenDay}><CalendarPlus className="h-4 w-4 text-white/45" /> Open day view</button>
        </>
      )}
    </motion.div>
  );
};
