import React, { memo, useEffect, useMemo, useRef } from 'react';
import { format, isSameDay, isSameMonth, isToday } from 'date-fns';
import { CheckCircle2, Clock3, MapPin, Plus } from 'lucide-react';
import {
  eventTimeLabel,
  getVisibleDays,
  occurrencesForDay,
  type CalendarOccurrence,
  type CalendarViewMode,
  type WorkspaceCalendarRecord,
} from './calendarModel';

interface CalendarGridProps {
  anchorDate: Date;
  mode: CalendarViewMode;
  occurrences: CalendarOccurrence[];
  calendars: WorkspaceCalendarRecord[];
  onCreate: (date: Date, kind?: 'event' | 'focus') => void;
  onEdit: (occurrence: CalendarOccurrence) => void;
  onContextMenu: (event: React.MouseEvent, date: Date, occurrence?: CalendarOccurrence) => void;
}

interface EventPillProps {
  occurrence: CalendarOccurrence;
  calendar: WorkspaceCalendarRecord | undefined;
  compact?: boolean;
  onEdit: (occurrence: CalendarOccurrence) => void;
  onContextMenu: (event: React.MouseEvent, date: Date, occurrence?: CalendarOccurrence) => void;
}

const EventPill = memo<EventPillProps>(({ occurrence, calendar, compact, onEdit, onContextMenu }) => {
  const color = calendar?.color || '#8b5cf6';
  const isDone = occurrence.status === 'done';
  const isCancelled = occurrence.status === 'cancelled';

  return (
    <button
      type="button"
      onClick={(event) => {
        event.stopPropagation();
        onEdit(occurrence);
      }}
      onContextMenu={(event) => {
        event.stopPropagation();
        onContextMenu(event, occurrence.occurrenceStart, occurrence);
      }}
      className={`group/event relative flex w-full items-center gap-1.5 overflow-hidden rounded-lg border px-2 text-left text-[11px] font-semibold outline-none transition hover:brightness-125 focus-visible:ring-2 focus-visible:ring-white/45 ${compact ? 'min-h-6 py-1' : 'min-h-8 py-1.5'} ${isCancelled ? 'opacity-45' : ''}`}
      style={{ backgroundColor: `${color}1f`, borderColor: `${color}45`, color }}
      title={`${occurrence.title} · ${eventTimeLabel(occurrence)}`}
    >
      <span className="h-1.5 w-1.5 shrink-0 rounded-full" style={{ backgroundColor: color }} />
      <span className={`min-w-0 flex-1 truncate ${isDone ? 'line-through opacity-65' : ''}`}>{occurrence.title}</span>
      {!compact ? <span className="shrink-0 text-[9px] opacity-55">{occurrence.all_day ? 'All day' : format(occurrence.occurrenceStart, 'HH:mm')}</span> : null}
      {isDone ? <CheckCircle2 className="h-3 w-3 shrink-0" /> : null}
    </button>
  );
});

EventPill.displayName = 'EventPill';

const WEEKDAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

const MonthGrid: React.FC<CalendarGridProps> = ({ anchorDate, occurrences, calendars, onCreate, onEdit, onContextMenu }) => {
  const days = useMemo(() => getVisibleDays(anchorDate, 'month'), [anchorDate]);
  const calendarById = useMemo(() => new Map(calendars.map((calendar) => [calendar.id, calendar])), [calendars]);

  return (
    <div className="h-full overflow-auto">
      <div className="min-w-[760px]">
        <div className="sticky top-0 z-20 grid grid-cols-7 border-b border-white/[0.07] bg-[#0b0b0d]/94 backdrop-blur-2xl">
          {WEEKDAY_LABELS.map((label) => (
            <div key={label} className="px-3 py-3 text-[10px] font-black uppercase tracking-[0.15em] text-white/30">{label}</div>
          ))}
        </div>
        <div className="grid grid-cols-7">
          {days.map((day) => {
            const dayOccurrences = occurrencesForDay(occurrences, day);
            const sameMonth = isSameMonth(day, anchorDate);
            return (
              <div
                key={day.toISOString()}
                onDoubleClick={() => onCreate(new Date(day.getFullYear(), day.getMonth(), day.getDate(), 9))}
                onContextMenu={(event) => onContextMenu(event, new Date(day.getFullYear(), day.getMonth(), day.getDate(), 9))}
                className={`group/day relative min-h-[132px] border-b border-r border-white/[0.055] p-2 transition-colors hover:bg-white/[0.02] ${sameMonth ? 'bg-transparent' : 'bg-black/18'}`}
              >
                <div className="mb-1.5 flex items-center justify-between">
                  <button type="button" onClick={() => onCreate(new Date(day.getFullYear(), day.getMonth(), day.getDate(), 9))} className={`grid h-7 min-w-7 place-items-center rounded-full px-1 text-xs font-bold transition ${isToday(day) ? 'bg-white text-black' : sameMonth ? 'text-white/65 hover:bg-white/[0.07] hover:text-white' : 'text-white/20 hover:text-white/50'}`} aria-label={`Add event on ${format(day, 'MMMM d')}`}>
                    {format(day, 'd')}
                  </button>
                  <Plus className="h-3.5 w-3.5 text-white/0 transition group-hover/day:text-white/25" />
                </div>
                <div className="space-y-1">
                  {dayOccurrences.slice(0, 3).map((occurrence) => (
                    <EventPill key={occurrence.occurrenceId} occurrence={occurrence} calendar={calendarById.get(occurrence.calendar_id)} compact onEdit={onEdit} onContextMenu={onContextMenu} />
                  ))}
                  {dayOccurrences.length > 3 ? (
                    <button type="button" onClick={() => onCreate(new Date(day.getFullYear(), day.getMonth(), day.getDate(), 9))} className="w-full rounded-lg px-2 py-1 text-left text-[10px] font-bold text-white/30 transition hover:bg-white/[0.05] hover:text-white/60">+ {dayOccurrences.length - 3} more</button>
                  ) : null}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

const HOUR_HEIGHT = 64;
const HOURS = Array.from({ length: 24 }, (_, hour) => hour);

const TimeGrid: React.FC<CalendarGridProps> = ({ anchorDate, mode, occurrences, calendars, onCreate, onEdit, onContextMenu }) => {
  const days = useMemo(() => getVisibleDays(anchorDate, mode), [anchorDate, mode]);
  const calendarById = useMemo(() => new Map(calendars.map((calendar) => [calendar.id, calendar])), [calendars]);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    requestAnimationFrame(() => {
      if (scrollRef.current) scrollRef.current.scrollTop = HOUR_HEIGHT * 7.25;
    });
  }, [mode]);

  const timedForDay = (day: Date) => occurrences.filter((occurrence) => (
    !occurrence.all_day
    && isSameDay(occurrence.occurrenceStart, day)
    && occurrence.occurrenceEnd.getTime() - occurrence.occurrenceStart.getTime() < 86_400_000
  ));
  const allDayForDay = (day: Date) => occurrencesForDay(occurrences, day).filter((occurrence) => (
    occurrence.all_day
    || occurrence.occurrenceEnd.getTime() - occurrence.occurrenceStart.getTime() >= 86_400_000
    || !isSameDay(occurrence.occurrenceStart, occurrence.occurrenceEnd)
  ));

  const dayMinWidth = mode === 'day' ? 'min-w-[460px]' : 'min-w-[900px]';

  return (
    <div ref={scrollRef} className="h-full overflow-auto">
      <div className={`${dayMinWidth} relative`}>
        <div className="sticky top-0 z-30 grid border-b border-white/[0.07] bg-[#0b0b0d]/95 pl-16 backdrop-blur-2xl" style={{ gridTemplateColumns: `repeat(${days.length}, minmax(0, 1fr))` }}>
          {days.map((day) => (
            <button key={day.toISOString()} type="button" onClick={() => onCreate(new Date(day.getFullYear(), day.getMonth(), day.getDate(), 9))} className="border-r border-white/[0.055] px-2 py-3 text-center transition hover:bg-white/[0.035]">
              <span className="block text-[9px] font-black uppercase tracking-[0.15em] text-white/30">{format(day, 'EEE')}</span>
              <span className={`mx-auto mt-1 grid h-8 w-8 place-items-center rounded-full text-sm font-bold ${isToday(day) ? 'bg-white text-black' : 'text-white/70'}`}>{format(day, 'd')}</span>
            </button>
          ))}
        </div>

        <div className="sticky top-[61px] z-20 grid min-h-10 border-b border-white/[0.07] bg-[#0b0b0d]/92 pl-16 backdrop-blur-xl" style={{ gridTemplateColumns: `repeat(${days.length}, minmax(0, 1fr))` }}>
          {days.map((day) => (
            <div key={`all-day-${day.toISOString()}`} className="space-y-1 border-r border-white/[0.055] p-1.5">
              {allDayForDay(day).slice(0, 2).map((occurrence) => (
                <EventPill key={occurrence.occurrenceId} occurrence={occurrence} calendar={calendarById.get(occurrence.calendar_id)} compact onEdit={onEdit} onContextMenu={onContextMenu} />
              ))}
            </div>
          ))}
        </div>

        <div className="relative pl-16" style={{ height: HOUR_HEIGHT * 24 }}>
          <div className="absolute inset-0 left-0 w-16">
            {HOURS.map((hour) => (
              <div key={hour} className="relative border-b border-white/[0.045] text-right" style={{ height: HOUR_HEIGHT }}>
                <span className="absolute -top-2.5 right-3 text-[10px] font-medium text-white/25">{String(hour).padStart(2, '0')}:00</span>
              </div>
            ))}
          </div>
          <div className="grid h-full" style={{ gridTemplateColumns: `repeat(${days.length}, minmax(0, 1fr))` }}>
            {days.map((day) => {
              const now = new Date();
              const showNow = isSameDay(day, now);
              const nowTop = ((now.getHours() * 60 + now.getMinutes()) / 60) * HOUR_HEIGHT;
              return (
                <div
                  key={`timed-${day.toISOString()}`}
                  className="relative border-r border-white/[0.055]"
                  onDoubleClick={(event) => {
                    const rect = event.currentTarget.getBoundingClientRect();
                    const minutes = Math.max(0, Math.min(23 * 60 + 45, Math.floor(((event.clientY - rect.top) / HOUR_HEIGHT) * 4) * 15));
                    const start = new Date(day);
                    start.setHours(Math.floor(minutes / 60), minutes % 60, 0, 0);
                    onCreate(start);
                  }}
                  onContextMenu={(event) => {
                    const rect = event.currentTarget.getBoundingClientRect();
                    const minutes = Math.max(0, Math.min(23 * 60 + 45, Math.floor(((event.clientY - rect.top) / HOUR_HEIGHT) * 4) * 15));
                    const start = new Date(day);
                    start.setHours(Math.floor(minutes / 60), minutes % 60, 0, 0);
                    onContextMenu(event, start);
                  }}
                >
                  {HOURS.map((hour) => <div key={hour} className="border-b border-white/[0.045]" style={{ height: HOUR_HEIGHT }} />)}
                  {showNow ? <div className="pointer-events-none absolute inset-x-0 z-20 flex items-center" style={{ top: nowTop }}><span className="-ml-1 h-2 w-2 rounded-full bg-rose-400" /><span className="h-px flex-1 bg-rose-400/70" /></div> : null}
                  {timedForDay(day).map((occurrence) => {
                    const minutesFromStart = occurrence.occurrenceStart.getHours() * 60 + occurrence.occurrenceStart.getMinutes();
                    const durationMinutes = Math.max(22, (occurrence.occurrenceEnd.getTime() - occurrence.occurrenceStart.getTime()) / 60_000);
                    const color = calendarById.get(occurrence.calendar_id)?.color || '#8b5cf6';
                    return (
                      <button
                        key={occurrence.occurrenceId}
                        type="button"
                        onClick={(event) => { event.stopPropagation(); onEdit(occurrence); }}
                        onContextMenu={(event) => { event.stopPropagation(); onContextMenu(event, occurrence.occurrenceStart, occurrence); }}
                        className={`absolute left-1 right-1 z-10 overflow-hidden rounded-xl border px-2.5 py-2 text-left outline-none transition hover:z-20 hover:brightness-125 focus-visible:z-20 focus-visible:ring-2 focus-visible:ring-white/55 ${occurrence.status === 'cancelled' ? 'opacity-45' : ''}`}
                        style={{
                          top: (minutesFromStart / 60) * HOUR_HEIGHT,
                          height: Math.max(30, (durationMinutes / 60) * HOUR_HEIGHT),
                          backgroundColor: `${color}22`,
                          borderColor: `${color}55`,
                          color,
                        }}
                      >
                        <span className={`block truncate text-[11px] font-bold ${occurrence.status === 'done' ? 'line-through opacity-65' : ''}`}>{occurrence.title}</span>
                        <span className="mt-0.5 block truncate text-[9px] opacity-60">{eventTimeLabel(occurrence)}</span>
                        {occurrence.location && durationMinutes >= 50 ? <span className="mt-1 flex items-center gap-1 truncate text-[9px] opacity-50"><MapPin className="h-2.5 w-2.5" />{occurrence.location}</span> : null}
                      </button>
                    );
                  })}
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

export const CalendarGrid: React.FC<CalendarGridProps> = (props) => {
  if (props.mode === 'month') return <MonthGrid {...props} />;
  return <TimeGrid {...props} />;
};

export const CalendarEmptyState = ({ onCreate }: { onCreate: () => void }) => (
  <div className="grid h-full min-h-80 place-items-center px-6 text-center">
    <div className="max-w-sm">
      <span className="mx-auto grid h-14 w-14 place-items-center rounded-full border border-white/[0.08] bg-white/[0.04] text-violet-200"><Clock3 className="h-5 w-5" /></span>
      <h3 className="mt-4 text-lg font-semibold text-white">Your agenda is clear</h3>
      <p className="mt-2 text-sm leading-6 text-white/40">Create an event, or right-click any day or time slot for the quick menu.</p>
      <button type="button" onClick={onCreate} className="mt-5 inline-flex h-10 items-center gap-2 rounded-full bg-white px-4 text-sm font-bold text-black"><Plus className="h-4 w-4" /> New event</button>
    </div>
  </div>
);
