      {onClose ? <button type="button" onClick={onClose} className="grid h-8 w-8 place-items-center rounded-full bg-white/[0.05] text-white/50" aria-label="Close agenda insights"><X className="h-4 w-4" /></button> : <Clock3 className="mt-1 h-4 w-4 text-white/20" />}
