export const WorkspaceCalendar: React.FC = () => {
  const { user } = useAuth();
  const [anchorDate, setAnchorDate] = useState(() => new Date());
  const [viewMode, setViewMode] = useState<CalendarViewMode>('month');
  const [calendars, setCalendars] = useState<WorkspaceCalendarRecord[]>([]);
  const [events, setEvents] = useState<WorkspaceCalendarEventRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [isLeftOpen, setIsLeftOpen] = useState(false);
  const [isRightOpen, setIsRightOpen] = useState(false);
  const [calendarMenuId, setCalendarMenuId] = useState<string | null>(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [dialogStart, setDialogStart] = useState<Date | null>(null);
  const [dialogStatus, setDialogStatus] = useState<CalendarEventStatus>('scheduled');
  const [editingEvent, setEditingEvent] = useState<WorkspaceCalendarEventRecord | null>(null);
  const [savingEvent, setSavingEvent] = useState(false);
  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const [aiSorting, setAiSorting] = useState(false);

  const range = useMemo(() => getCalendarRange(anchorDate, viewMode), [anchorDate, viewMode]);
  const rangeStartIso = range.start.toISOString();
  const rangeEndIso = range.end.toISOString();

  const loadCalendarData = useCallback(async (silent = false) => {
    if (!user) return;
    if (silent) setRefreshing(true);
    else setLoading(true);
    setLoadError(null);

    try {
      const calendarsRequest = supabase
        .from('workspace_calendars')
        .select(CALENDAR_SELECT)
        .eq('user_id', user.id)
        .order('position', { ascending: true })
        .order('created_at', { ascending: true });
      const eventsRequest = supabase
        .from('workspace_calendar_events')
        .select(EVENT_SELECT)
        .eq('user_id', user.id)
        .lte('starts_at', rangeEndIso)
        .or(`ends_at.gte.${rangeStartIso},recurrence_rule.neq.none`)
        .order('starts_at', { ascending: true });

      const [calendarResult, eventResult] = await Promise.all([calendarsRequest, eventsRequest]);
      if (calendarResult.error) throw calendarResult.error;
      if (eventResult.error) throw eventResult.error;

      let nextCalendars = (calendarResult.data || []) as WorkspaceCalendarRecord[];
      if (nextCalendars.length === 0) {
        const { data: created, error: createError } = await supabase
          .from('workspace_calendars')
          .insert({ user_id: user.id, name: 'Personal', color: CALENDAR_COLORS[0], position: 0 })
          .select(CALENDAR_SELECT)
          .single();

        if (createError?.code === '23505') {
          const { data: existing, error: existingError } = await supabase
            .from('workspace_calendars')
            .select(CALENDAR_SELECT)
            .eq('user_id', user.id)
            .order('position', { ascending: true });
          if (existingError) throw existingError;
          nextCalendars = (existing || []) as WorkspaceCalendarRecord[];
        } else if (createError) {
          throw createError;
        } else if (created) {
          nextCalendars = [created as WorkspaceCalendarRecord];
        }
      }

      setCalendars(nextCalendars);
      setEvents((eventResult.data || []) as WorkspaceCalendarEventRecord[]);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Calendar data could not be loaded.';
      setLoadError(message);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [rangeEndIso, rangeStartIso, user]);

  useEffect(() => {
    void loadCalendarData();
  }, [loadCalendarData]);

  useEffect(() => {
    if (!user) return;
    const channel = supabase
      .channel(`workspace-calendar:${user.id}`)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'workspace_calendars', filter: `user_id=eq.${user.id}` }, () => void loadCalendarData(true))
      .on('postgres_changes', { event: '*', schema: 'public', table: 'workspace_calendar_events', filter: `user_id=eq.${user.id}` }, () => void loadCalendarData(true))
      .subscribe();
    return () => { void supabase.removeChannel(channel); };
  }, [loadCalendarData, user]);

  useEffect(() => {
    const closeCalendarMenu = (event: PointerEvent) => {
      if (!(event.target as HTMLElement).closest('[data-calendar-source-menu]')) setCalendarMenuId(null);
    };
    document.addEventListener('pointerdown', closeCalendarMenu);
    return () => document.removeEventListener('pointerdown', closeCalendarMenu);
  }, []);

  const calendarById = useMemo(() => new Map(calendars.map((calendar) => [calendar.id, calendar])), [calendars]);
  const visibleCalendarIds = useMemo(() => new Set(calendars.filter((calendar) => calendar.is_visible).map((calendar) => calendar.id)), [calendars]);
  const visibleEvents = useMemo(() => events.filter((event) => visibleCalendarIds.has(event.calendar_id)), [events, visibleCalendarIds]);
  const occurrences = useMemo(() => expandCalendarEvents(visibleEvents, range), [range, visibleEvents]);
  const aiCalendars = useMemo(() => calendars.filter((calendar) => calendar.ai_sort_enabled), [calendars]);
  const upcoming = useMemo(() => {
    const now = Date.now();
    return occurrences
      .filter((occurrence) => occurrence.occurrenceEnd.getTime() >= now && occurrence.status !== 'cancelled' && occurrence.status !== 'done')
      .sort((left, right) => {
        const leftCalendar = calendarById.get(left.calendar_id);
        const rightCalendar = calendarById.get(right.calendar_id);
        if (left.calendar_id === right.calendar_id && leftCalendar?.ai_sort_enabled && rightCalendar?.ai_sort_enabled) {
          const leftRank = left.ai_rank ?? Number.MAX_SAFE_INTEGER;
          const rightRank = right.ai_rank ?? Number.MAX_SAFE_INTEGER;
          if (leftRank !== rightRank) return leftRank - rightRank;
        }
        return left.occurrenceStart.getTime() - right.occurrenceStart.getTime();
      });
  }, [calendarById, occurrences]);

  const openCreate = useCallback((date: Date, kind: 'event' | 'focus' = 'event') => {
    setContextMenu(null);
    setEditingEvent(null);
    setDialogStart(date);
    setDialogStatus(kind === 'focus' ? 'focus' : 'scheduled');
    setDialogOpen(true);
  }, []);

  const openEdit = useCallback((occurrence: CalendarOccurrence) => {
    setContextMenu(null);
    setEditingEvent(occurrence);
    setDialogStart(occurrence.occurrenceStart);
    setDialogStatus(occurrence.status);
    setDialogOpen(true);
  }, []);

  const saveEvent = async (draft: CalendarEventDraft) => {
    if (!user) return;
    setSavingEvent(true);
    try {
      const payload = { ...draft, user_id: user.id, ai_rank: null, ai_sorted_at: null };
      const result = editingEvent
        ? await supabase.from('workspace_calendar_events').update(payload).eq('id', editingEvent.id).eq('user_id', user.id)
        : await supabase.from('workspace_calendar_events').insert(payload);
      if (result.error) throw result.error;
      appToast(editingEvent ? 'Event updated.' : 'Event created.', 'success');
      setDialogOpen(false);
      setEditingEvent(null);
      await loadCalendarData(true);
    } catch (error) {
      appToast(error instanceof Error ? error.message : 'The event could not be saved.', 'error');
    } finally {
      setSavingEvent(false);
    }
  };

  const deleteEvent = async (event: WorkspaceCalendarEventRecord) => {
    if (!user) return;
    const confirmed = await destructiveAction({
      title: 'Delete event?',
      description: event.recurrence_rule === 'none' ? `“${event.title}” will be permanently removed.` : `This removes every occurrence of “${event.title}”.`,
      confirmText: 'Delete event',
    });
    if (!confirmed) return;
    const { error } = await supabase.from('workspace_calendar_events').delete().eq('id', event.id).eq('user_id', user.id);
    if (error) {
      appToast(error.message, 'error');
      return;
    }
    setDialogOpen(false);
    setEditingEvent(null);
    setContextMenu(null);
    appToast('Event deleted.', 'success');
    await loadCalendarData(true);
  };

  const duplicateOccurrence = async (occurrence: CalendarOccurrence) => {
    if (!user) return;
    const { error } = await supabase.from('workspace_calendar_events').insert({
      user_id: user.id,
      calendar_id: occurrence.calendar_id,
      title: `${occurrence.title} copy`.slice(0, 160),
      description: occurrence.description,
      location: occurrence.location,
      starts_at: occurrence.occurrenceStart.toISOString(),
      ends_at: occurrence.occurrenceEnd.toISOString(),
      all_day: occurrence.all_day,
      status: occurrence.status === 'done' ? 'scheduled' : occurrence.status,
      priority: occurrence.priority,
      recurrence_rule: 'none',
      recurrence_until: null,
    });
    setContextMenu(null);
    if (error) appToast(error.message, 'error');
    else {
      appToast('Event duplicated.', 'success');
      await loadCalendarData(true);
    }
  };

  const toggleOccurrenceDone = async (occurrence: CalendarOccurrence) => {
    if (!user) return;
    const nextStatus = occurrence.status === 'done' ? 'scheduled' : 'done';
    const { error } = await supabase.from('workspace_calendar_events').update({ status: nextStatus }).eq('id', occurrence.id).eq('user_id', user.id);
    setContextMenu(null);
    if (error) appToast(error.message, 'error');
    else await loadCalendarData(true);
  };

  const toggleCalendarField = async (calendar: WorkspaceCalendarRecord, field: 'is_visible' | 'ai_sort_enabled') => {
    if (!user) return;
    const nextValue = !calendar[field];
    setCalendars((current) => current.map((item) => item.id === calendar.id ? { ...item, [field]: nextValue } : item));
    const { error } = await supabase.from('workspace_calendars').update({ [field]: nextValue }).eq('id', calendar.id).eq('user_id', user.id);
    if (error) {
      setCalendars((current) => current.map((item) => item.id === calendar.id ? { ...item, [field]: calendar[field] } : item));
      appToast(error.message, 'error');
    }
  };

  const createCalendar = async () => {
    if (!user) return;
    const name = await requestInput({
      title: 'New calendar',
      description: 'Give this calendar a clear name. You can enable AI ordering after it is created.',
      label: 'Calendar name',
      placeholder: 'Projects',
      confirmText: 'Create calendar',
      required: true,
      validate: (value) => value.trim().length > 80 ? 'Use 80 characters or fewer.' : null,
    });
    if (!name?.trim()) return;
    const color = CALENDAR_COLORS[calendars.length % CALENDAR_COLORS.length];
    const { error } = await supabase.from('workspace_calendars').insert({ user_id: user.id, name: name.trim(), color, position: calendars.length });
    if (error) appToast(error.code === '23505' ? 'A calendar with that name already exists.' : error.message, 'error');
    else {
      appToast('Calendar created.', 'success');
      await loadCalendarData(true);
    }
  };

  const renameCalendar = async (calendar: WorkspaceCalendarRecord) => {
    if (!user) return;
    const name = await requestInput({
      title: 'Rename calendar',
      description: 'Events remain connected to this calendar.',
      label: 'Calendar name',
      defaultValue: calendar.name,
      confirmText: 'Save name',
      required: true,
      validate: (value) => value.trim().length > 80 ? 'Use 80 characters or fewer.' : null,
    });
    if (!name?.trim() || name.trim() === calendar.name) return;
    const { error } = await supabase.from('workspace_calendars').update({ name: name.trim() }).eq('id', calendar.id).eq('user_id', user.id);
    if (error) appToast(error.code === '23505' ? 'A calendar with that name already exists.' : error.message, 'error');
    else await loadCalendarData(true);
  };

  const deleteCalendar = async (calendar: WorkspaceCalendarRecord) => {
    if (!user || calendars.length <= 1) return;
    const confirmed = await destructiveAction({
      title: `Delete ${calendar.name}?`,
      description: 'The calendar and every event inside it will be permanently removed.',
      confirmText: 'Delete calendar',
    });
    if (!confirmed) return;
    const { error } = await supabase.from('workspace_calendars').delete().eq('id', calendar.id).eq('user_id', user.id);
    if (error) appToast(error.message, 'error');
    else {
      appToast('Calendar deleted.', 'success');
      await loadCalendarData(true);
    }
  };

  const sortWithAi = async () => {
    if (!user || aiSorting) return;
    const enabledIds = new Set(aiCalendars.map((calendar) => calendar.id));
    const eligible = events.filter((event) => enabledIds.has(event.calendar_id) && event.status !== 'cancelled' && event.status !== 'done');
    if (eligible.length < 2) {
      appToast('Add at least two active events to an AI-enabled calendar.', 'info');
      return;
    }

    setAiSorting(true);
    try {
      const { werseeAi } = await import('../../../ai/client');
      const response = await werseeAi.generateText({
        contents: [
          'Order these real calendar events by execution priority.',
          'Consider explicit priority, start time, duration, status, and title. Do not invent facts and do not change event times.',
          'Return strict JSON only in this exact shape: {"orderedEventIds":["id"]}. Include every supplied ID exactly once.',
          `CURRENT_TIME: ${new Date().toISOString()}`,
          `EVENTS: ${JSON.stringify(eligible.map((event) => ({ id: event.id, title: event.title, startsAt: event.starts_at, endsAt: event.ends_at, priority: event.priority, status: event.status, calendar: calendarById.get(event.calendar_id)?.name || event.calendar_id })))}`,
        ].join('\n'),
        config: { temperature: 0.1, maxOutputTokens: 700 },
      });
      const json = response.text.match(/\{[\s\S]*\}/)?.[0];
      if (!json) throw new Error('Wersee AI returned no usable priority order.');
      const parsed = JSON.parse(json) as { orderedEventIds?: unknown };
      if (!Array.isArray(parsed.orderedEventIds)) throw new Error('Wersee AI returned an invalid priority order.');
      const allowed = new Set(eligible.map((event) => event.id));
      const orderedIds = parsed.orderedEventIds.filter((id): id is string => typeof id === 'string' && allowed.has(id));
      if (orderedIds.length !== eligible.length || new Set(orderedIds).size !== eligible.length) {
        throw new Error('Wersee AI did not return every enabled event exactly once.');
      }
      const sortedAt = new Date().toISOString();
      const updates = await Promise.all(orderedIds.map((id, aiRank) => supabase.from('workspace_calendar_events').update({ ai_rank: aiRank, ai_sorted_at: sortedAt }).eq('id', id).eq('user_id', user.id)));
      const updateError = updates.find((result) => result.error)?.error;
      if (updateError) throw updateError;
      appToast('AI priority order saved.', 'success');
      await loadCalendarData(true);
    } catch (error) {
      appToast(error instanceof Error ? error.message : 'Wersee AI could not sort this agenda.', 'error');
    } finally {
      setAiSorting(false);
    }
  };

  const handleContextMenu = useCallback((mouseEvent: React.MouseEvent, date: Date, occurrence?: CalendarOccurrence) => {
    mouseEvent.preventDefault();
    setContextMenu({ x: mouseEvent.clientX, y: mouseEvent.clientY, date, occurrence: occurrence || null });
  }, []);

  const setMode = (mode: CalendarViewMode) => {
    setViewMode(mode);
    setContextMenu(null);
  };

  if (!user) return null;

  return (
    <div className="relative flex h-full min-h-0 overflow-hidden bg-[#08080a] text-white">
      <aside className="hidden w-[238px] shrink-0 border-r border-white/[0.065] lg:block">
        <CalendarSourcesSidebar anchorDate={anchorDate} calendars={calendars} activeMenuId={calendarMenuId} onAnchorChange={setAnchorDate} onCreateCalendar={createCalendar} onToggleVisible={(calendar) => void toggleCalendarField(calendar, 'is_visible')} onToggleAi={(calendar) => void toggleCalendarField(calendar, 'ai_sort_enabled')} onRename={(calendar) => void renameCalendar(calendar)} onDelete={(calendar) => void deleteCalendar(calendar)} onMenuChange={setCalendarMenuId} />
      </aside>

      <section className="flex min-w-0 flex-1 flex-col">
        <header className="flex min-h-[68px] shrink-0 items-center gap-2 border-b border-white/[0.065] bg-[#0d0d10]/90 px-3 backdrop-blur-2xl sm:px-4">
          <button type="button" onClick={() => setIsLeftOpen(true)} className="grid h-10 w-10 shrink-0 place-items-center rounded-full text-white/45 transition hover:bg-white/[0.06] hover:text-white lg:hidden" aria-label="Open calendars"><PanelLeft className="h-4 w-4" /></button>
          <div className="flex items-center gap-1">
            <button type="button" onClick={() => setAnchorDate(getNextAnchor(anchorDate, viewMode, -1))} className="grid h-9 w-9 place-items-center rounded-full text-white/40 transition hover:bg-white/[0.06] hover:text-white" aria-label={`Previous ${viewMode}`}><ChevronLeft className="h-4 w-4" /></button>
            <button type="button" onClick={() => setAnchorDate(new Date())} className="hidden h-9 rounded-full px-3 text-[11px] font-bold text-white/55 transition hover:bg-white/[0.06] hover:text-white sm:block">Today</button>
            <button type="button" onClick={() => setAnchorDate(getNextAnchor(anchorDate, viewMode, 1))} className="grid h-9 w-9 place-items-center rounded-full text-white/40 transition hover:bg-white/[0.06] hover:text-white" aria-label={`Next ${viewMode}`}><ChevronRight className="h-4 w-4" /></button>
          </div>
          <h1 className="min-w-0 flex-1 truncate px-1 text-sm font-semibold tracking-tight text-white sm:text-base">{calendarTitle(anchorDate, viewMode)}</h1>
          <div className="hidden rounded-full border border-white/[0.07] bg-black/25 p-1 sm:flex" role="group" aria-label="Calendar view">
            {(['day', 'week', 'month'] as CalendarViewMode[]).map((mode) => (
              <button key={mode} type="button" onClick={() => setMode(mode)} className={`relative h-8 rounded-full px-3 text-[10px] font-bold capitalize transition ${viewMode === mode ? 'text-black' : 'text-white/42 hover:text-white'}`}>
                {viewMode === mode ? <motion.span layoutId="calendar-view-pill" className="absolute inset-0 rounded-full bg-white" transition={{ type: 'spring', stiffness: 420, damping: 34 }} /> : null}
                <span className="relative z-10">{mode}</span>
              </button>
            ))}
          </div>
          <Select className="mb-0 w-[104px] sm:hidden" value={viewMode} onChange={(value) => setMode(value as CalendarViewMode)} options={[{ value: 'day', label: 'Day' }, { value: 'week', label: 'Week' }, { value: 'month', label: 'Month' }]} />
          <button type="button" onClick={() => void loadCalendarData(true)} disabled={refreshing} className="hidden h-9 w-9 place-items-center rounded-full text-white/30 transition hover:bg-white/[0.06] hover:text-white md:grid" aria-label="Refresh agenda"><RefreshCw className={`h-3.5 w-3.5 ${refreshing ? 'animate-spin' : ''}`} /></button>
          <button type="button" onClick={() => openCreate(startOfHour(addHours(new Date(), 1)))} className="flex h-10 shrink-0 items-center gap-2 rounded-full bg-white px-3.5 text-[11px] font-bold text-black shadow-[0_8px_30px_rgba(255,255,255,.1)] transition hover:bg-white/85 active:scale-[0.98]"><Plus className="h-4 w-4" /><span className="hidden md:inline">New event</span></button>
          <button type="button" onClick={() => setIsRightOpen(true)} className="grid h-10 w-10 shrink-0 place-items-center rounded-full text-white/45 transition hover:bg-white/[0.06] hover:text-white 2xl:hidden" aria-label="Open agenda insights"><PanelRight className="h-4 w-4" /></button>
        </header>

        <div className="relative min-h-0 flex-1">
          {loading ? (
            <div className="grid h-full place-items-center"><div className="flex items-center gap-3 rounded-full border border-white/[0.07] bg-white/[0.03] px-4 py-2 text-xs text-white/45"><RefreshCw className="h-3.5 w-3.5 animate-spin" /> Loading your agenda…</div></div>
          ) : loadError ? (
            <div className="grid h-full place-items-center px-6 text-center">
              <div className="max-w-md rounded-[2rem] border border-amber-300/15 bg-amber-400/[0.055] p-7">
                <AlertTriangle className="mx-auto h-6 w-6 text-amber-300" />
                <h2 className="mt-4 text-lg font-semibold">Agenda storage is unavailable</h2>
                <p className="mt-2 text-sm leading-6 text-white/40">No placeholder events are shown. Check the calendar database migration and try again.</p>
                <button type="button" onClick={() => void loadCalendarData()} className="mt-5 inline-flex h-10 items-center gap-2 rounded-full bg-white px-4 text-xs font-bold text-black"><RefreshCw className="h-3.5 w-3.5" /> Try again</button>
                {import.meta.env.DEV ? <p className="mt-4 break-words text-[10px] text-red-200/50">{loadError}</p> : null}
              </div>
            </div>
          ) : (
            <CalendarGrid anchorDate={anchorDate} mode={viewMode} occurrences={occurrences} calendars={calendars} onCreate={openCreate} onEdit={openEdit} onContextMenu={handleContextMenu} />
          )}
          {refreshing && !loading ? <div className="pointer-events-none absolute right-3 top-3 z-30 rounded-full border border-white/[0.08] bg-black/65 px-3 py-1.5 text-[9px] font-bold uppercase tracking-wider text-white/45 backdrop-blur-xl">Syncing</div> : null}
        </div>
      </section>

      <aside className="hidden w-[286px] shrink-0 border-l border-white/[0.065] 2xl:block">
        <CalendarInsightsSidebar upcoming={upcoming} calendarById={calendarById} aiCalendars={aiCalendars} aiSorting={aiSorting} onSortWithAi={() => void sortWithAi()} onEdit={openEdit} />
      </aside>

      <AnimatePresence>
        {isLeftOpen ? (
          <>
            <motion.button type="button" aria-label="Close calendars" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setIsLeftOpen(false)} className="fixed inset-0 z-[280] bg-black/55 backdrop-blur-sm lg:hidden" />
            <motion.aside initial={{ opacity: 0, x: -28, scale: 0.98 }} animate={{ opacity: 1, x: 0, scale: 1 }} exit={{ opacity: 0, x: -22, scale: 0.98 }} transition={{ type: 'spring', stiffness: 360, damping: 34 }} className="fixed bottom-3 left-3 top-3 z-[290] w-[min(88vw,300px)] overflow-hidden rounded-[2rem] border border-white/[0.1] shadow-2xl lg:hidden">
              <CalendarSourcesSidebar anchorDate={anchorDate} calendars={calendars} activeMenuId={calendarMenuId} onAnchorChange={setAnchorDate} onCreateCalendar={createCalendar} onToggleVisible={(calendar) => void toggleCalendarField(calendar, 'is_visible')} onToggleAi={(calendar) => void toggleCalendarField(calendar, 'ai_sort_enabled')} onRename={(calendar) => void renameCalendar(calendar)} onDelete={(calendar) => void deleteCalendar(calendar)} onMenuChange={setCalendarMenuId} onClose={() => setIsLeftOpen(false)} />
            </motion.aside>
          </>
        ) : null}
        {isRightOpen ? (
          <>
            <motion.button type="button" aria-label="Close agenda insights" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setIsRightOpen(false)} className="fixed inset-0 z-[280] bg-black/55 backdrop-blur-sm 2xl:hidden" />
            <motion.aside initial={{ opacity: 0, x: 28, scale: 0.98 }} animate={{ opacity: 1, x: 0, scale: 1 }} exit={{ opacity: 0, x: 22, scale: 0.98 }} transition={{ type: 'spring', stiffness: 360, damping: 34 }} className="fixed bottom-3 right-3 top-3 z-[290] w-[min(88vw,320px)] overflow-hidden rounded-[2rem] border border-white/[0.1] shadow-2xl 2xl:hidden">
              <CalendarInsightsSidebar upcoming={upcoming} calendarById={calendarById} aiCalendars={aiCalendars} aiSorting={aiSorting} onSortWithAi={() => void sortWithAi()} onEdit={(occurrence) => { setIsRightOpen(false); openEdit(occurrence); }} onClose={() => setIsRightOpen(false)} />
            </motion.aside>
          </>
        ) : null}
      </AnimatePresence>

      <CalendarEventDialog isOpen={dialogOpen} calendars={calendars} event={editingEvent} initialStart={dialogStart} initialStatus={dialogStatus} saving={savingEvent} onClose={() => { if (!savingEvent) { setDialogOpen(false); setEditingEvent(null); } }} onSave={saveEvent} onDelete={deleteEvent} />

      {contextMenu ? (
        <CalendarContextMenu
          x={contextMenu.x}
          y={contextMenu.y}
          occurrence={contextMenu.occurrence}
          onClose={() => setContextMenu(null)}
          onCreate={(kind) => openCreate(contextMenu.date, kind)}
          onOpenDay={() => { setAnchorDate(contextMenu.date); setMode('day'); setContextMenu(null); }}
          onEdit={() => contextMenu.occurrence && openEdit(contextMenu.occurrence)}
          onDuplicate={() => contextMenu.occurrence && void duplicateOccurrence(contextMenu.occurrence)}
          onToggleDone={() => contextMenu.occurrence && void toggleOccurrenceDone(contextMenu.occurrence)}
          onDelete={() => contextMenu.occurrence && void deleteEvent(contextMenu.occurrence)}
        />
      ) : null}
    </div>
  );
};
