import React, { useEffect, useId, useState } from 'react';
import { AnimatePresence, motion } from 'motion/react';
import { CalendarDays, Clock3, MapPin, Trash2, X } from 'lucide-react';
import { addHours, startOfHour } from 'date-fns';
import { Select } from '../../ui/Select';
import { appToast } from '../../../lib/feedback';
import {
  toDateTimeLocal,
  type CalendarEventPriority,
  type CalendarEventStatus,
  type CalendarRecurrence,
  type WorkspaceCalendarEventRecord,
  type WorkspaceCalendarRecord,
} from './calendarModel';

export interface CalendarEventDraft {
  calendar_id: string;
  title: string;
  description: string;
  location: string;
  starts_at: string;
  ends_at: string;
  all_day: boolean;
  status: CalendarEventStatus;
  priority: CalendarEventPriority;
  recurrence_rule: CalendarRecurrence;
  recurrence_until: string | null;
}

interface CalendarEventDialogProps {
  isOpen: boolean;
  calendars: WorkspaceCalendarRecord[];
  event: WorkspaceCalendarEventRecord | null;
  initialStart: Date | null;
  initialStatus?: CalendarEventStatus;
  saving: boolean;
  onClose: () => void;
  onSave: (draft: CalendarEventDraft) => Promise<void>;
  onDelete: (event: WorkspaceCalendarEventRecord) => Promise<void>;
}

const FIELD_CLASS = 'h-12 w-full rounded-2xl border border-white/[0.08] bg-white/[0.045] px-4 text-sm text-white outline-none transition placeholder:text-white/25 focus:border-violet-300/40 focus:bg-white/[0.07] focus:ring-2 focus:ring-violet-400/15';

export const CalendarEventDialog: React.FC<CalendarEventDialogProps> = ({
  isOpen,
  calendars,
  event,
  initialStart,
  initialStatus = 'scheduled',
  saving,
  onClose,
  onSave,
  onDelete,
}) => {
  const titleId = useId();
  const [title, setTitle] = useState('');
  const [calendarId, setCalendarId] = useState('');
  const [startsAt, setStartsAt] = useState('');
  const [endsAt, setEndsAt] = useState('');
  const [allDay, setAllDay] = useState(false);
  const [location, setLocation] = useState('');
  const [description, setDescription] = useState('');
  const [priority, setPriority] = useState<CalendarEventPriority>('normal');
  const [status, setStatus] = useState<CalendarEventStatus>('scheduled');
  const [recurrence, setRecurrence] = useState<CalendarRecurrence>('none');
  const [recurrenceUntil, setRecurrenceUntil] = useState('');

  useEffect(() => {
    if (!isOpen) return;
    const fallbackStart = startOfHour(initialStart || addHours(new Date(), 1));
    const fallbackEnd = addHours(fallbackStart, 1);
    setTitle(event?.title || (initialStatus === 'focus' ? 'Focus block' : ''));
    setCalendarId(event?.calendar_id || calendars.find((calendar) => calendar.is_visible)?.id || calendars[0]?.id || '');
    setStartsAt(toDateTimeLocal(event ? new Date(event.starts_at) : fallbackStart));
    setEndsAt(toDateTimeLocal(event ? new Date(event.ends_at) : fallbackEnd));
    setAllDay(event?.all_day || false);
    setLocation(event?.location || '');
    setDescription(event?.description || '');
    setPriority(event?.priority || (initialStatus === 'focus' ? 'high' : 'normal'));
    setStatus(event?.status || initialStatus);
    setRecurrence(event?.recurrence_rule || 'none');
    setRecurrenceUntil(event?.recurrence_until || '');
  }, [calendars, event, initialStart, initialStatus, isOpen]);

  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (keyboardEvent: KeyboardEvent) => {
      if (keyboardEvent.key === 'Escape' && !saving) onClose();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose, saving]);

  const submit = async (formEvent: React.FormEvent) => {
    formEvent.preventDefault();
    const cleanTitle = title.trim();
    const start = new Date(startsAt);
    const end = new Date(endsAt);

    if (!cleanTitle) {
      appToast('An event title is required.', 'error');
      return;
    }
    if (!calendarId) {
      appToast('Create or select a calendar first.', 'error');
      return;
    }
    if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end <= start) {
      appToast('The event end must be after its start.', 'error');
      return;
    }

    await onSave({
      calendar_id: calendarId,
      title: cleanTitle,
      description: description.trim(),
      location: location.trim(),
      starts_at: start.toISOString(),
      ends_at: end.toISOString(),
      all_day: allDay,
      status,
      priority,
      recurrence_rule: recurrence,
      recurrence_until: recurrence === 'none' || !recurrenceUntil ? null : recurrenceUntil,
    });
  };

  return (
    <AnimatePresence>
      {isOpen ? (
        <>
          <motion.button
            type="button"
            aria-label="Close event editor"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => !saving && onClose()}
            className="fixed inset-0 z-[330] cursor-default bg-black/55 backdrop-blur-md"
          />
          <motion.div
            role="dialog"
            aria-modal="true"
            aria-labelledby={titleId}
            initial={{ opacity: 0, y: 22, scale: 0.97 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 16, scale: 0.98 }}
            transition={{ type: 'spring', stiffness: 360, damping: 34 }}
            className="fixed inset-x-3 bottom-3 z-[340] max-h-[calc(100dvh-1.5rem)] overflow-y-auto rounded-[2rem] border border-white/[0.1] bg-[#111114]/96 text-white shadow-[0_36px_120px_rgba(0,0,0,.72)] backdrop-blur-3xl sm:inset-x-auto sm:bottom-auto sm:left-1/2 sm:top-1/2 sm:w-[min(92vw,680px)] sm:-translate-x-1/2 sm:-translate-y-1/2"
          >
            <form onSubmit={submit}>
              <div className="sticky top-0 z-20 flex items-center justify-between border-b border-white/[0.07] bg-[#111114]/92 px-5 py-4 backdrop-blur-2xl sm:px-6">
                <div>
                  <p className="text-[10px] font-black uppercase tracking-[0.2em] text-violet-300/70">Agenda</p>
                  <h2 id={titleId} className="mt-1 text-xl font-semibold tracking-tight">{event ? 'Edit event' : 'New event'}</h2>
                </div>
                <button type="button" onClick={onClose} disabled={saving} className="grid h-10 w-10 place-items-center rounded-full bg-white/[0.055] text-white/55 transition hover:bg-white/[0.09] hover:text-white disabled:opacity-40" aria-label="Close">
                  <X className="h-4 w-4" />
                </button>
              </div>

              <div className="space-y-5 px-5 py-5 sm:px-6 sm:py-6">
                <label className="block">
                  <span className="mb-2 block text-[11px] font-bold uppercase tracking-[0.14em] text-white/40">Title</span>
                  <input autoFocus value={title} onChange={(inputEvent) => setTitle(inputEvent.target.value)} maxLength={160} placeholder="What are you planning?" className={`${FIELD_CLASS} text-base font-medium`} />
                </label>

                <div className="grid gap-4 sm:grid-cols-2">
                  <Select
                    label="Calendar"
                    className="mb-0"
                    value={calendarId}
                    onChange={setCalendarId}
                    options={calendars.map((calendar) => ({ value: calendar.id, label: calendar.name }))}
                    placeholder="Select calendar"
                  />
                  <Select
                    label="Priority"
                    className="mb-0"
                    value={priority}
                    onChange={(value) => setPriority(value as CalendarEventPriority)}
                    options={[
                      { value: 'low', label: 'Low' },
                      { value: 'normal', label: 'Normal' },
                      { value: 'high', label: 'High' },
                      { value: 'urgent', label: 'Urgent' },
                    ]}
                  />
                </div>

                <div className="rounded-[1.5rem] border border-white/[0.07] bg-white/[0.025] p-4">
                  <div className="mb-4 flex items-center justify-between gap-4">
                    <div className="flex items-center gap-3">
                      <span className="grid h-9 w-9 place-items-center rounded-full bg-violet-400/10 text-violet-200"><Clock3 className="h-4 w-4" /></span>
                      <div>
                        <p className="text-sm font-semibold">Time</p>
                        <p className="text-xs text-white/35">Local time on this device</p>
                      </div>
                    </div>
                    <button type="button" role="switch" aria-checked={allDay} onClick={() => setAllDay((value) => !value)} className={`relative h-7 w-12 rounded-full p-1 transition ${allDay ? 'bg-violet-500' : 'bg-white/10'}`}>
                      <motion.span layout className="block h-5 w-5 rounded-full bg-white shadow" animate={{ x: allDay ? 20 : 0 }} transition={{ type: 'spring', stiffness: 430, damping: 30 }} />
                    </button>
                  </div>
                  <div className="grid gap-3 sm:grid-cols-2">
                    <label className="block text-xs font-medium text-white/45">Starts
                      <input type="datetime-local" value={startsAt} onChange={(inputEvent) => setStartsAt(inputEvent.target.value)} className={`${FIELD_CLASS} mt-1.5 [color-scheme:dark]`} />
                    </label>
                    <label className="block text-xs font-medium text-white/45">Ends
                      <input type="datetime-local" value={endsAt} onChange={(inputEvent) => setEndsAt(inputEvent.target.value)} className={`${FIELD_CLASS} mt-1.5 [color-scheme:dark]`} />
                    </label>
                  </div>
                </div>

                <div className="grid gap-4 sm:grid-cols-2">
                  <Select
                    label="Repeats"
                    className="mb-0"
                    value={recurrence}
                    onChange={(value) => setRecurrence(value as CalendarRecurrence)}
                    options={[
                      { value: 'none', label: 'Does not repeat' },
                      { value: 'daily', label: 'Every day' },
                      { value: 'weekly', label: 'Every week' },
                      { value: 'monthly', label: 'Every month' },
                    ]}
                  />
                  {recurrence !== 'none' ? (
                    <label className="block text-sm font-medium text-gray-300">Repeat until
                      <input type="date" value={recurrenceUntil} min={startsAt.slice(0, 10)} onChange={(inputEvent) => setRecurrenceUntil(inputEvent.target.value)} className={`${FIELD_CLASS} mt-1.5 [color-scheme:dark]`} />
                    </label>
                  ) : (
                    <Select
                      label="Status"
                      className="mb-0"
                      value={status}
                      onChange={(value) => setStatus(value as CalendarEventStatus)}
                      options={[
                        { value: 'scheduled', label: 'Scheduled' },
                        { value: 'focus', label: 'Focus' },
                        { value: 'done', label: 'Done' },
                        { value: 'cancelled', label: 'Cancelled' },
                      ]}
                    />
                  )}
                </div>

                <label className="block">
                  <span className="mb-2 flex items-center gap-2 text-[11px] font-bold uppercase tracking-[0.14em] text-white/40"><MapPin className="h-3.5 w-3.5" /> Location</span>
                  <input value={location} onChange={(inputEvent) => setLocation(inputEvent.target.value)} maxLength={240} placeholder="Add a location or meeting link" className={FIELD_CLASS} />
                </label>

                <label className="block">
                  <span className="mb-2 block text-[11px] font-bold uppercase tracking-[0.14em] text-white/40">Notes</span>
                  <textarea value={description} onChange={(inputEvent) => setDescription(inputEvent.target.value)} maxLength={5000} rows={4} placeholder="Add context, an outcome, or prep notes" className={`${FIELD_CLASS} h-auto min-h-28 resize-y py-3 leading-6`} />
                </label>
              </div>

              <div className="sticky bottom-0 flex items-center justify-between gap-3 border-t border-white/[0.07] bg-[#111114]/94 px-5 py-4 backdrop-blur-2xl sm:px-6">
                {event ? (
                  <button type="button" disabled={saving} onClick={() => onDelete(event)} className="flex h-11 items-center gap-2 rounded-full px-4 text-sm font-semibold text-red-300 transition hover:bg-red-500/10 disabled:opacity-40">
                    <Trash2 className="h-4 w-4" /> Delete
                  </button>
                ) : <span />}
                <div className="flex items-center gap-2">
                  <button type="button" disabled={saving} onClick={onClose} className="h-11 rounded-full px-5 text-sm font-semibold text-white/55 transition hover:bg-white/[0.06] hover:text-white disabled:opacity-40">Cancel</button>
                  <button type="submit" disabled={saving || calendars.length === 0} className="flex h-11 items-center gap-2 rounded-full bg-white px-5 text-sm font-bold text-black shadow-[0_8px_32px_rgba(255,255,255,.12)] transition hover:bg-white/88 active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-45">
                    <CalendarDays className="h-4 w-4" /> {saving ? 'Saving…' : event ? 'Save changes' : 'Add event'}
                  </button>
                </div>
              </div>
            </form>
          </motion.div>
        </>
      ) : null}
    </AnimatePresence>
  );
};
