import {
  addDays,
  addMonths,
  addWeeks,
  differenceInCalendarDays,
  differenceInCalendarMonths,
  differenceInCalendarWeeks,
  eachDayOfInterval,
  endOfDay,
  endOfMonth,
  endOfWeek,
  format,
  isSameDay,
  parseISO,
  startOfDay,
  startOfMonth,
  startOfWeek,
} from 'date-fns';

export type CalendarViewMode = 'day' | 'week' | 'month';
export type CalendarEventStatus = 'scheduled' | 'focus' | 'done' | 'cancelled';
export type CalendarEventPriority = 'low' | 'normal' | 'high' | 'urgent';
export type CalendarRecurrence = 'none' | 'daily' | 'weekly' | 'monthly';

export interface WorkspaceCalendarRecord {
  id: string;
  user_id: string;
  name: string;
  color: string;
  is_visible: boolean;
  ai_sort_enabled: boolean;
  position: number;
  created_at: string;
  updated_at: string;
}

export interface WorkspaceCalendarEventRecord {
  id: string;
  calendar_id: string;
  user_id: string;
  title: string;
  description: string;
  location: string;
  starts_at: string;
  ends_at: string;
  all_day: boolean;
  status: CalendarEventStatus;
  priority: CalendarEventPriority;
  recurrence_rule: CalendarRecurrence;
  recurrence_until: string | null;
  ai_rank: number | null;
  ai_sorted_at: string | null;
  created_at: string;
  updated_at: string;
}

export interface CalendarOccurrence extends WorkspaceCalendarEventRecord {
  occurrenceId: string;
  occurrenceStart: Date;
  occurrenceEnd: Date;
}

export interface CalendarRange {
  start: Date;
  end: Date;
}

export const CALENDAR_COLORS = [
  '#8b5cf6',
  '#3b82f6',
  '#06b6d4',
  '#10b981',
  '#f59e0b',
  '#f97316',
  '#ec4899',
] as const;

export const getCalendarRange = (anchor: Date, mode: CalendarViewMode): CalendarRange => {
  if (mode === 'day') {
    return { start: startOfDay(anchor), end: endOfDay(anchor) };
  }

  if (mode === 'week') {
    return {
      start: startOfWeek(anchor, { weekStartsOn: 1 }),
      end: endOfWeek(anchor, { weekStartsOn: 1 }),
    };
  }

  return {
    start: startOfWeek(startOfMonth(anchor), { weekStartsOn: 1 }),
    end: endOfWeek(endOfMonth(anchor), { weekStartsOn: 1 }),
  };
};

export const getVisibleDays = (anchor: Date, mode: CalendarViewMode) => {
  const range = getCalendarRange(anchor, mode);
  return eachDayOfInterval(range);
};

export const getMiniMonthDays = (anchor: Date) => {
  const start = startOfWeek(startOfMonth(anchor), { weekStartsOn: 1 });
  const end = endOfWeek(endOfMonth(anchor), { weekStartsOn: 1 });
  return eachDayOfInterval({ start, end });
};

const addRecurrence = (date: Date, recurrence: Exclude<CalendarRecurrence, 'none'>, amount = 1) => {
  if (recurrence === 'daily') return addDays(date, amount);
  if (recurrence === 'weekly') return addWeeks(date, amount);
  return addMonths(date, amount);
};

const recurrenceJump = (
  eventStart: Date,
  target: Date,
  recurrence: Exclude<CalendarRecurrence, 'none'>,
) => {
  if (target <= eventStart) return 0;
  if (recurrence === 'daily') return Math.max(0, differenceInCalendarDays(target, eventStart) - 1);
  if (recurrence === 'weekly') {
    return Math.max(0, differenceInCalendarWeeks(target, eventStart, { weekStartsOn: 1 }) - 1);
  }
  return Math.max(0, differenceInCalendarMonths(target, eventStart) - 1);
};

export const expandCalendarEvents = (
  events: WorkspaceCalendarEventRecord[],
  range: CalendarRange,
): CalendarOccurrence[] => {
  const occurrences: CalendarOccurrence[] = [];
  const rangeStart = range.start.getTime();
  const rangeEnd = range.end.getTime();

  events.forEach((event) => {
    const eventStart = parseISO(event.starts_at);
    const eventEnd = parseISO(event.ends_at);
    const duration = Math.max(1, eventEnd.getTime() - eventStart.getTime());

    if (event.recurrence_rule === 'none') {
      if (eventStart.getTime() <= rangeEnd && eventEnd.getTime() >= rangeStart) {
        occurrences.push({
          ...event,
          occurrenceId: event.id,
          occurrenceStart: eventStart,
          occurrenceEnd: eventEnd,
        });
      }
      return;
    }

    const recurrence = event.recurrence_rule;
    const target = new Date(rangeStart - duration);
    const jump = recurrenceJump(eventStart, target, recurrence);
    let occurrenceStart = addRecurrence(eventStart, recurrence, jump);
    let occurrenceEnd = new Date(occurrenceStart.getTime() + duration);
    const recurrenceLimit = event.recurrence_until
      ? endOfDay(parseISO(event.recurrence_until)).getTime()
      : Number.POSITIVE_INFINITY;

    while (occurrenceEnd.getTime() < rangeStart && occurrenceStart.getTime() <= recurrenceLimit) {
      occurrenceStart = addRecurrence(occurrenceStart, recurrence);
      occurrenceEnd = new Date(occurrenceStart.getTime() + duration);
    }

    let generated = 0;
    while (
      occurrenceStart.getTime() <= rangeEnd
      && occurrenceStart.getTime() <= recurrenceLimit
      && generated < 400
    ) {
      if (occurrenceEnd.getTime() >= rangeStart) {
        occurrences.push({
          ...event,
          occurrenceId: `${event.id}:${occurrenceStart.toISOString()}`,
          occurrenceStart,
          occurrenceEnd,
        });
      }
      occurrenceStart = addRecurrence(occurrenceStart, recurrence);
      occurrenceEnd = new Date(occurrenceStart.getTime() + duration);
      generated += 1;
    }
  });

  return occurrences.sort((left, right) => {
    const timeDifference = left.occurrenceStart.getTime() - right.occurrenceStart.getTime();
    if (timeDifference !== 0) return timeDifference;
    return left.title.localeCompare(right.title);
  });
};

export const occurrencesForDay = (occurrences: CalendarOccurrence[], day: Date) =>
  occurrences.filter((occurrence) =>
    isSameDay(occurrence.occurrenceStart, day)
    || (occurrence.occurrenceStart < startOfDay(day) && occurrence.occurrenceEnd > startOfDay(day)),
  );

export const calendarTitle = (anchor: Date, mode: CalendarViewMode) => {
  if (mode === 'day') return format(anchor, 'EEEE, MMMM d');
  if (mode === 'week') {
    const range = getCalendarRange(anchor, mode);
    return range.start.getMonth() === range.end.getMonth()
      ? `${format(range.start, 'MMMM d')} – ${format(range.end, 'd, yyyy')}`
      : `${format(range.start, 'MMM d')} – ${format(range.end, 'MMM d, yyyy')}`;
  }
  return format(anchor, 'MMMM yyyy');
};

export const toDateTimeLocal = (date: Date) => format(date, "yyyy-MM-dd'T'HH:mm");

export const eventTimeLabel = (occurrence: CalendarOccurrence) => {
  if (occurrence.all_day) return 'All day';
  return `${format(occurrence.occurrenceStart, 'HH:mm')} – ${format(occurrence.occurrenceEnd, 'HH:mm')}`;
};

export const getNextAnchor = (anchor: Date, mode: CalendarViewMode, direction: -1 | 1) => {
  if (mode === 'day') return addDays(anchor, direction);
  if (mode === 'week') return addWeeks(anchor, direction);
  return addMonths(anchor, direction);
};
